export function makePreset(id){const p=SCENE_PRESETS.find(x=>x.id===id)||SCENE_PRESETS[0];return {...DEFAULTS,...p.patch};}
export function horizonRg(spin){return 1+Math.sqrt(Math.max(0,1-spin*spin));}
export function iscoRg(spin){const a=Math.min(.998,Math.max(0,spin));const z1=1+Math.cbrt(1-a*a)*(Math.cbrt(1+a)+Math.cbrt(1-a));const z2=Math.sqrt(3*a*a+z1*z1);return 3+z2-Math.sqrt((3-z1)*(3+z1+2*z2));}
